/**
 * Return the retail pickup placement set for a map and measured layout.
 *
 * @param {'amboy'|'gracia'|'river'} mapId
 * @param {'amboy'|'gracia'|'310m'|'lap'} [layout] river defaults to '310m'
 * @returns {{schema:string, mapId:string, source:string,
 *   pickups:Array<{id:string,type:string,x:number,y:number,z:number,
 *     respawnSeconds:number|null,lapMin:number,lapMax:number,source:string}>,
 *   unsupported:Array<{id:string,type:string,reason:string}>}}
 */
export function placementsFor(mapId, layout) {
  const map = RUNTIME_PLACEMENT_DATA.maps[mapId];
  if (!map) {
    fail('unknown map ' + JSON.stringify(mapId) + ' (use ' +
      Object.keys(RUNTIME_PLACEMENT_DATA.maps).join(', ') + ')');
  }
  const layouts = MAP_LAYOUTS[mapId];
  const selected = layout === undefined || layout === null ? map.defaultLayout : layout;
  if (!layouts.includes(selected)) {
    fail('unsupported layout ' + JSON.stringify(selected) + ' for ' + mapId +
      ' (use ' + layouts.join(', ') + ')');
  }
  const pickups = map.pickups.map((pickup) => {
    const projection = pickup.projections[selected];
    if (!projection) fail('pickup ' + pickup.id + ' has no ' + selected + ' projection');
    return {
      id: pickup.id,
      type: pickup.type,
      x: pickup.x,
      y: pickup.y,
      z: pickup.z,
      respawnSeconds: pickup.respawnSeconds,
      lapMin: pickup.activationLap > 0 ? pickup.activationLap : 0,
      lapMax: pickup.activationLap > 0 ? pickup.activationLap : map.laps[selected],
      source: pickupSource(map, pickup, projection, selected)
    };
  });
  return {
    schema: RUNTIME_PLACEMENT_SCHEMA,
    mapId,
    source: map.source + (map.defaultLayout === selected ? '' : '; layout ' + selected),
    pickups,
    unsupported: map.unsupported.map((row) => ({
      id: row.id,
      type: row.type,
      reason: row.reason
    }))
  };
}
